import type { Db, User } from './types.js';

export interface UserPage {
  users: User[];
  total: number;
  page: number;
  pageSize: number;
}

export async function listUsersPage(db: Db, page: number, pageSize: number): Promise<UserPage> {
  if (!Number.isInteger(page) || page < 1) throw new RangeError('page must be an integer >= 1');
  if (!Number.isInteger(pageSize) || pageSize < 1 || pageSize > 200) {
    throw new RangeError('pageSize must be an integer between 1 and 200');
  }
  const offset = (page - 1) * pageSize;
  const users = await db.query<User>(
    'SELECT id, name, email FROM users ORDER BY id LIMIT $1 OFFSET $2',
    [pageSize, offset],
  );
  const counts = await db.query<{ count: string }>('SELECT count(*) AS count FROM users');
  const total = Number(counts[0]?.count ?? 0);
  return { users, total, page, pageSize };
}
